-- Proyecto JULIÁN. Schema independiente de los demás proyectos.
CREATE SCHEMA IF NOT EXISTS parcial_julian;
CREATE TABLE IF NOT EXISTS parcial_julian.usuarios (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nombre VARCHAR(160) NOT NULL, correo VARCHAR(180) UNIQUE NOT NULL, rol VARCHAR(24) NOT NULL CHECK (rol IN ('ADMINISTRADOR','COORDINACION','DIRECTOR','EVALUADOR','ESTUDIANTE')), programa VARCHAR(150), sal VARCHAR(32) NOT NULL, clave_hash CHAR(64) NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE, creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS parcial_julian.ideas (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, titulo VARCHAR(220) NOT NULL, objetivo TEXT NOT NULL, descripcion TEXT NOT NULL, estado VARCHAR(24) NOT NULL DEFAULT 'DISPONIBLE' CHECK (estado IN ('DISPONIBLE','CERRADA')), creado_por BIGINT REFERENCES parcial_julian.usuarios(id), creado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS parcial_julian.anteproyectos (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, codigo VARCHAR(28) UNIQUE, idea_id BIGINT REFERENCES parcial_julian.ideas(id), estudiante_id BIGINT NOT NULL REFERENCES parcial_julian.usuarios(id), director_id BIGINT REFERENCES parcial_julian.usuarios(id), evaluador_id BIGINT REFERENCES parcial_julian.usuarios(id), titulo VARCHAR(220) NOT NULL, resumen TEXT NOT NULL, objetivos TEXT NOT NULL, enlace_archivo VARCHAR(900), estado VARCHAR(30) NOT NULL DEFAULT 'BORRADOR', calificacion NUMERIC(3,2), etapa_actual VARCHAR(35) NOT NULL DEFAULT 'ANTEPROYECTO', proyecto_final_url VARCHAR(900), calificacion_final NUMERIC(3,2), version_final INTEGER NOT NULL DEFAULT 1, creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, actualizado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS parcial_julian.revisiones (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, anteproyecto_id BIGINT NOT NULL REFERENCES parcial_julian.anteproyectos(id), revisor_id BIGINT NOT NULL REFERENCES parcial_julian.usuarios(id), tipo VARCHAR(16) NOT NULL CHECK(tipo IN ('DIRECTOR','EVALUADOR')), decision VARCHAR(22) NOT NULL, nota NUMERIC(3,2) CHECK(nota BETWEEN 0 AND 5), observaciones TEXT NOT NULL, etapa VARCHAR(35) NOT NULL DEFAULT 'ANTEPROYECTO', fecha TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS parcial_julian.calendario (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, evento VARCHAR(220) NOT NULL, inicio DATE NOT NULL, fin DATE NOT NULL, CHECK (fin>=inicio));
CREATE TABLE IF NOT EXISTS parcial_julian.formatos (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, nombre VARCHAR(220) NOT NULL UNIQUE, version VARCHAR(90) NOT NULL, url VARCHAR(900) NOT NULL);
CREATE TABLE IF NOT EXISTS parcial_julian.historial (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, anteproyecto_id BIGINT NOT NULL REFERENCES parcial_julian.anteproyectos(id), actor_id BIGINT REFERENCES parcial_julian.usuarios(id), evento VARCHAR(140) NOT NULL, detalle TEXT, fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_julian_estudiante ON parcial_julian.anteproyectos(estudiante_id,estado);
CREATE INDEX IF NOT EXISTS idx_julian_director ON parcial_julian.anteproyectos(director_id,estado);
CREATE INDEX IF NOT EXISTS idx_julian_evaluador ON parcial_julian.anteproyectos(evaluador_id,estado);
